#include <juce_data_structures/juce_data_structures.h>
int main(){juce::SQLiteDatabase db;auto f=juce::File::getSpecialLocation(juce::File::tempDirectory).getChildFile("magdrum-test.sqlite3");if(!db.open(f))return 1;if(!db.executeSQL("CREATE TABLE IF NOT EXISTS samples(path TEXT PRIMARY KEY)"))return 2;if(!db.executeSQL("INSERT OR IGNORE INTO samples(path) VALUES('/test/kick.wav')"))return 3;if(!db.executeSQL("INSERT OR IGNORE INTO samples(path) VALUES('/test/kick.wav')"))return 4;juce::SQLiteStatement q(db,"SELECT COUNT(*) FROM samples");if(!q.next()||q.getColumnValue(0).getIntValue()!=1)return 5;return 0;}
